void z3_cfg_logic(Z3Cfg *c)
{
    switch (c->logic) {
    case Z3_LOGIC_OVERWORLDGLITCHES:
        c->canSuperBunny = 1;
        c->canFakeFlipper = 1;
        c->canSuperSpeed = 1;
        c->canBootsClip = 1;
        c->canMirrorClip = 1;
        c->canWaterWalk = 1;
        c->canDungeonRevive = 1;
        break;
    case Z3_LOGIC_HYBRIDMAJORGLITCHES:
        c->canSuperBunny = 1;
        c->canFakeFlipper = 1;
        c->canSuperSpeed = 1;
        c->canBootsClip = 1;
        c->canMirrorClip = 1;
        c->canWaterWalk = 1;
        c->canDungeonRevive = 1;
        c->canOneFrameClipUW = 1;
        break;
    case Z3_LOGIC_MAJORGLITCHES:
        c->canSuperBunny = 1;
        c->canFakeFlipper = 1;
        c->canSuperSpeed = 1;
        c->canBootsClip = 1;
        c->canMirrorClip = 1;
        c->canWaterWalk = 1;
        c->canMirrorWrap = 1;
        c->canDungeonRevive = 1;
        c->canOWYBA = 1;
        c->canOneFrameClipOW = 1;
        c->canOneFrameClipUW = 1;
        c->canTransitionWrapped = 1;
        break;
    default:
        break;
    }
}

static int Inverted_TurtleRock_m_accountForWastingKeyOnTrinexDoor(const Z3World *w, const Z3Items *it, int withoutWaste, int withWaste);
static int Inverted_TurtleRock_m_canReachBottom(const Z3World *w, const Z3Items *it);
